#!/usr/bin/env python3
"""Build/check the separately scoped completion audit. Offline checks are not source verification."""
from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP
import sys
ROOT=Path(__file__).resolve().parents[1]
fee='https://www.boc.cn/ebanking/service/cs1/200905/t20090506_990712.html'
board='https://www.boc.cn/sourcedb/whpj/'
safe='https://www.safe.gov.cn/tianjin/2026/0713/3088.html'
quota='https://www.safe.gov.cn/ningxia/2022/0929/1997.html'
irs='https://www.irs.gov/individuals/international-taxpayers/foreign-currency-and-currency-exchange-rates'
def money(x): return f'{x.quantize(Decimal(".01"),rounding=ROUND_HALF_UP):,.2f}'
rows=[]
for amount in range(10000,400001,10000):
    cny=Decimal(amount)*Decimal('6.6851')
    charge=min(max(cny*Decimal('.001'),Decimal(50)),Decimal(260))+Decimal(150)
    rows.append(f'<tr><th scope="row">${amount:,}</th><td>¥{money(cny)}</td><td>¥{money(charge)} / ${money(charge/Decimal("6.6851"))}</td><td aria-label="Unverified total"></td><td><a href="{board}">Rate</a> · <a href="{fee}">Tariff</a></td></tr>')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Completion audit — China money</title><style>body{font:17px/1.6 system-ui;color:#172b40;background:#f5f7fb;margin:auto;max-width:1100px;padding:22px}h1,h2{line-height:1.2}section{background:white;padding:24px;margin:20px 0;border:1px solid #dce3ea;border-radius:14px}a{color:#075ea4}nav{display:flex;gap:16px;flex-wrap:wrap}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}thead{background:#edf3f9}.warn{border-left:5px solid #c77400}small{color:#405469}</style><nav><a href="index.html">Main dashboard</a><a href="s775-methods.html">24 methods</a><a href="s775-steps.html">Execution steps</a><a href="s775-cost-10k-400k.html">Method costs</a><a href="#flags">Flagged for Review</a></nav><h1>China money: independent completion audit</h1><p>Official pages read on 10 November 2026. This is a supplemental audit, not a claim that every inherited line was independently reverified.</p><section><h2>Executive summary: eligibility comes before price</h2><p><strong>First route to investigate:</strong> documented, lawful current-account income converted and wired by a regulated bank. SAFE specifically permits foreign individuals to purchase foreign exchange against valid identity and source-of-funds material showing the amount, including tax documentation. This supports a documented-income route; it does not establish that every balance or every US citizen qualifies.</p><p><a href="SAFE">SAFE: foreign individual remuneration</a>. Its domestic-person FAQ also explains that the $50,000 annual convenience amount is not an absolute ceiling for qualifying documented transactions: <a href="QUOTA">official FAQ</a>. Do not assume that domestic-person convenience rules apply to a foreign passport holder.</p><p><strong>No exact least-tax winner is established.</strong> The source and ownership of the funds, prior tax treatment, currency basis, account classification and bank eligibility are not known. A cheaper transfer channel does not establish lower income tax. IRS requires relevant income and expense items to be translated into USD using the applicable timing rules: <a href="IRS">IRS currency guidance</a>. This page leaves personal tax and all-in totals blank.</p></section><section><h2>Practical bank workflow</h2><ol><li>Identify the legal owner and source of each portion of the balance. Do not treat business, inheritance, gifts, property proceeds and wages as interchangeable.</li><li>For the foreign-individual current-income route, assemble valid identity, evidence of the source and transaction amount, and tax documentation. The exact additional checklist remains bank-specific.</li><li>Submit the genuine transaction to the bank for eligibility review; ask the bank to identify the actual obstacle and any claimed tax by legal basis.</li><li>Compare the executable USD selling rate and itemized transfer fees, including correspondent and receiving fees, before authorizing conversion.</li><li>After approval, convert and wire to the correctly identified recipient. Retain the rate confirmation, source evidence, tax evidence and wire receipt.</li></ol><p>Steps 1 and 3–5 are practical recommendations, not assertions of a universal mandatory procedure. The official document requirement is <a href="SAFE">SAFE article 59 explanation</a>; published tariff exceptions and actual-rate disclaimer are <a href="FEE">BOC tariff</a> and <a href="BOARD">BOC board</a>. No funds were moved and no account-specific approval is represented.</p></section><section><h2>$10,000–$400,000: freshly sourced fee-only illustration</h2><p>BOC USD board displayed <strong>668.51 CNY per US$100</strong> selling, 665.71 buying, timestamp <strong>2026/11/10 17:39:58</strong> (as displayed). Thus the illustrative selling rate is 6.6851 CNY/USD. This is a snapshot, not an executable quote. Source: <a href="BOARD">BOC</a>.</p><p>Published personal e-banking cross-border wire tariff: 0.1% of amount, ¥50 minimum / ¥260 maximum, plus ¥150 cable outside Hong Kong/Macao/Taiwan. BOC expressly allows agreed, promotional and local variations. Formula: min(max(USD × 6.6851 × 0.001, 50), 260) + 150. USD fee equivalents divide by 6.6851; these are <strong>derived illustrations, not officially quoted USD charges</strong>. Eligibility for e-banking at these sizes is not established. <a href="FEE">Official tariff</a>.</p><p class="warn">USD amount means gross currency purchased, not net dollars received. Fees are modeled as additional CNY. No invented midpoint spread, receiving fee, intermediary fee, tax, or all-in total is included. Blank total cells mean <strong>UNVERIFIED</strong>, not zero. For comparisons of other methods, see the existing <a href="s775-cost-10k-400k.html">method cost tables</a> and <a href="cost-tables.html">800-row schedule</a>; those are inherited models, not fresh quotes.</p><div class="scroll"><table><thead><tr><th>Gross USD</th><th>Conversion CNY</th><th>BOC fee / USD equivalent</th><th>All-in total (unverified)</th><th>Official sources</th></tr></thead><tbody>ROWS</tbody></table></div></section><section id="flags" class="warn"><h2>Flagged for Review</h2><ul><li><strong>Incomplete provenance:</strong> inherited <code>data/s775_sources.csv</code> includes S41 fetched_utc 2026-11-10T10:50:00Z, later than this session’s audit time. That timestamp cannot establish a past retrieval during this audit. The associated IRS claim is not newly verified here. See <a href="s775-sources.html">inherited register</a> and <a href="https://www.irs.gov/individuals/international-taxpayers/figuring-the-foreign-earned-income-exclusion">suggested IRS review source</a>.</li><li><strong>Moving FX board:</strong> inherited 6.6903 CNY/USD ask differs from the 6.6851 reading obtained here. This alone does not prove either earlier reading wrong, but older figures must not be marketed as current executable quotes. <a href="BOARD">Official board</a>.</li><li><strong>Model outputs ≠ official values:</strong> midpoint opportunity costs, hypothetical multi-year quota schedules, and fee arithmetic are analytical scenarios. Official links verify inputs, not a personalized final bill. <a href="FEE">Tariff exceptions</a>.</li><li><strong>Unknown facts:</strong> exact source-tax liability, US tax, FX basis, penalties, eligibility and receiving/intermediary charges are unverified and blank in this audit. <a href="IRS">IRS timing guidance</a>; <a href="SAFE">SAFE documentation</a>.</li><li><strong>Scope:</strong> structural validators passed across the inherited site; they cannot verify truth merely from an official-looking URL. This session independently read only the five official sources linked in this audit. See also <a href="s775-flagged-review.html">existing flags</a> and <a href="review.html">legacy review</a>.</li></ul></section><footer>Educational research, not individualized legal or tax advice. Automated research cannot substitute for bank authentication or legally required customer documents.</footer></html>'''
for key,value in {'ROWS':''.join(rows),'SAFE':safe,'QUOTA':quota,'IRS':irs,'FEE':fee,'BOARD':board}.items(): html=html.replace(key,value)
p=ROOT/'completion-audit.html'
if '--build' in sys.argv: p.write_text(html)
assert p.read_text()==html,'Stale completion audit'
assert len(rows)==40
assert '¥410.00 / $61.33' in html
assert html.count('aria-label="Unverified total"')==40
print('PASS: 40 source-linked fee illustrations, blank all-in totals, reproducible page; not a network verification.')
